            exclDump("Not ", t1, "; ");
        }
        // And vice versa.
        exclDump("\nChecking for supertype exclusion of ", other, ": ");
        Set<FType> oexcl = other.getExcludes();
        for (FType t1 : this.getTransitiveExtends()) {
            if (oexcl.contains(t1)) {
